function modalFormalReport(){
  const d=state.data;const teaching=d.teaching.filter(x=>!x.academic_year||x.academic_year===d.academic_year);const classes=[...new Map(teaching.map(x=>[x.class_id,{id:x.class_id,name:x.class_name}])).values()];
  if(!classes.length)return toast('Belum ada penugasan','Atur penugasan guru, kelas, dan mata pelajaran terlebih dahulu.','error');
  const initialClass=classes.some(x=>String(x.id)===String(state.filters.reportClass))?state.filters.reportClass:classes[0].id;
  openModal('Buat Laporan Hasil Belajar',`<div class="formal-modal-intro"><div>▧</div><p><b>Dokumen formal berkop sekolah</b><span>Guru mata pelajaran ditentukan otomatis dari penugasan aktif.</span></p></div><form id="learningReportForm" class="form-grid"><label class="full">Jenis laporan<select id="learningMode" class="form-control" name="mode"><option value="individual">Individual · untuk orang tua/wali</option><option value="class">Rekap kelas · untuk kepala sekolah</option></select></label><label>Kelas<select id="learningClass" class="form-control" name="class_id" required>${classes.map(x=>`<option value="${x.id}" ${String(x.id)===String(initialClass)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Mata pelajaran<select id="learningSubject" class="form-control" name="subject_id" required></select></label><label class="full" id="learningStudentField">Peserta didik<select id="learningStudent" class="form-control" name="student_id" required></select></label><label>Tanggal laporan<input class="form-control" name="report_date" type="date" value="${localDateValue()}" required></label><label class="check-line"><input type="checkbox" name="include_principal" value="1"><span><b>Sertakan kepala sekolah</b><small>Tambahkan ruang tanda tangan kepala sekolah.</small></span></label><div id="reportTeacherNotice" class="teacher-resolution full"></div><div class="report-output-choice full"><button class="btn btn-secondary" type="submit" value="excel">↓ Unduh Excel Formal</button><button class="btn btn-primary" type="submit" value="print">▧ Buka Cetak / PDF</button></div></form>`,'Laporan resmi');
  syncLearningReportFields();
}
function syncLearningReportFields(){
  const classSelect=$('#learningClass'),subjectSelect=$('#learningSubject'),studentSelect=$('#learningStudent'),mode=$('#learningMode');if(!classSelect||!subjectSelect||!studentSelect||!mode)return;
  const d=state.data,classId=Number(classSelect.value),oldSubject=subjectSelect.value;const matching=d.teaching.filter(x=>x.class_id===classId&&(!x.academic_year||x.academic_year===d.academic_year));const subjects=[...new Map(matching.map(x=>[x.subject_id,{id:x.subject_id,name:x.subject_name}])).values()];
  subjectSelect.innerHTML=subjects.map(x=>`<option value="${x.id}" ${String(x.id)===String(oldSubject||state.filters.reportSubject)?'selected':''}>${esc(x.name)}</option>`).join('');
  const students=d.students.filter(x=>x.class_id===classId&&x.academic_year===d.academic_year);studentSelect.innerHTML=students.map(x=>`<option value="${x.id}">${String(x.attendance_no).padStart(2,'0')} · ${esc(x.full_name)}</option>`).join('');
  const individual=mode.value==='individual';$('#learningStudentField').classList.toggle('hidden',!individual);studentSelect.required=individual;
  const subjectId=Number(subjectSelect.value),resolved=matching.filter(x=>x.subject_id===subjectId),notice=$('#reportTeacherNotice');
  if(resolved.length===1){notice.className='teacher-resolution full ready';notice.innerHTML=`<span>✓</span><div><b>Guru terpilih otomatis</b><small>${esc(resolved[0].teacher_name)} · ${esc(resolved[0].class_name)} / ${esc(resolved[0].subject_name)}</small></div>`;}else if(resolved.length>1){notice.className='teacher-resolution full warning';notice.innerHTML='<span>!</span><div><b>Penugasan ganda ditemukan</b><small>Admin perlu merapikan penugasan sebelum laporan dibuat.</small></div>';}else{notice.className='teacher-resolution full warning';notice.innerHTML='<span>!</span><div><b>Guru belum dapat ditentukan</b><small>Pilih kombinasi kelas dan mata pelajaran yang memiliki penugasan.</small></div>';}
}
function modalAssignment(id=0){const d=state.data,teach=d.teaching,a=id&&d.assignments.find(x=>Number(x.id)===Number(id));const local=value=>{if(!value)return '';const date=new Date(value),offset=date.getTimezoneOffset()*60000;return new Date(date-offset).toISOString().slice(0,16)};openModal(a?'Edit Tugas atau Proyek':'Buat Tugas atau Proyek',`<form id="assignmentForm" class="form-grid"><input type="hidden" name="id" value="${a?.id||''}"><label class="full">Judul tugas<input class="form-control" name="title" value="${esc(a?.title||'')}" placeholder="Contoh: Laporan Percobaan Fotosintesis" required></label><label>Kelas & mata pelajaran<select id="teachingSelect" class="form-control" required><option value="">Pilih penugasan</option>${teach.map(x=>`<option value="${x.class_id}|${x.subject_id}" ${Number(x.class_id)===Number(a?.class_id)&&Number(x.subject_id)===Number(a?.subject_id)?'selected':''}>${esc(x.class_name)} · ${esc(x.subject_name)}</option>`).join('')}</select></label><label>Tenggat<input class="form-control" type="datetime-local" name="due_at" value="${local(a?.due_at)}" required></label><label>Jenis tugas<select class="form-control" name="task_type"><option ${a?.task_type==='Harian'?'selected':''}>Harian</option><option ${a?.task_type==='Proyek'?'selected':''}>Proyek</option></select></label><label>Jenis asesmen<select class="form-control" name="assessment_type"><option ${a?.assessment_type==='Formatif'?'selected':''}>Formatif</option><option ${a?.assessment_type==='Sumatif'?'selected':''}>Sumatif</option><option ${a?.assessment_type==='Proyek'?'selected':''}>Proyek</option></select></label><label>Nilai maksimum<input class="form-control" type="number" name="max_score" value="${a?.max_score||100}" min="1" required></label>${a?`<label>Status<select class="form-control" name="status"><option value="published" ${a.status==='published'?'selected':''}>Terbit</option><option value="archived" ${a.status==='archived'?'selected':''}>Batalkan / arsipkan</option></select></label>`:''}<label class="full">Tujuan Pembelajaran (TP)<textarea class="form-control" name="tp" placeholder="Tuliskan kompetensi yang hendak dicapai...">${esc(a?.tp||'')}</textarea></label><label class="full">Petunjuk tugas<textarea class="form-control" name="description" placeholder="Jelaskan langkah dan ketentuan pengumpulan...">${esc(a?.description||'')}</textarea></label><div class="form-actions full"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">${a?'Simpan Perubahan':'Terbitkan Tugas'}</button></div></form>`,'Pembelajaran');}
