function modalManageAttendance(id){const d=state.data,s=d.attendance.find(x=>x.id===id),rec=d.attendance_records.filter(x=>x.session_id===id);openModal(`Absensi ${s.class_name}`,`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div><b style="font-size:12px">${esc(s.subject_name)} · ${esc(s.topic)}</b><p class="muted" style="font-size:10px;margin:4px 0">${fmtDate(s.session_date)}${s.mode==='code'?' · sesi historis':''}</p></div><span class="badge ${s.status==='open'?'green':'gray'}">${s.status==='open'?'Dibuka':'Selesai'}</span></div><div class="table-wrap attendance-sheet"><table class="data-table" style="min-width:520px"><thead><tr><th>No.</th><th>Nama siswa</th><th>Status</th></tr></thead><tbody>${rec.map(r=>`<tr><td>${esc(r.attendance_no)}</td><td><b>${esc(r.student_name)}</b></td><td><select class="status-select ${['Belum','Hadir','Sakit','Izin','Alpa'].includes(r.status)?r.status:'Belum'}" data-attendance-status data-session="${id}" data-student="${r.student_id}" ${s.status==='closed'?'disabled':''}>${['Belum','Hadir','Sakit','Izin','Alpa'].map(x=>`<option ${x===r.status?'selected':''}>${x}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Tutup</button>${s.status==='open'?`<button class="btn btn-danger" data-action="close-attendance" data-id="${id}">Akhiri Sesi</button>`:''}</div>`,'Rekap pertemuan');}
